A {\bf Hopf $\pi$-brace} structure over a family of coalgebras $H=\{H_\alpha,\Delta_\alpha,\varepsilon_\alpha\}_{\alpha\in\pi}$ consisting of the following datum:
\begin{enumerate}[\quad\rm(1)]
\item a Hopf $\pi$-algebra structure $(H, \cdot, 1, S)$ ($(H,\cdot,S)$ or $H$ for short),
\item a Hopf $\pi$-algebra structure $(H, \circ, 1_{\circ}, T)$ ($(H,\circ,T)$ or $H_{\circ}$ for short),
\item the compatible condition
\begin{equation} \label{eq:Hbrace}
g\circ(h\ell)=(g_{(1,\alpha)}\circ h)S_{\alpha}(g_{(2,\alpha)})(g_{(3,\alpha)}\circ \ell),
\end{equation}
for all $g\in H_\alpha,h\in H_\beta,\ell\in H_\gamma, ~\alpha,\beta,\gamma\in\pi$.
\end{enumerate}

\label{lem:truco}
Let $(H,\cdot,\circ)$ be a Hopf $\pi$-brace. Then
\begin{equation}\label{eq:Hbrace2}
  S_{\alpha\beta}(g_{(1,\alpha)}\circ h)g_{(2,\alpha)} = S_{\alpha}(g_{(1,\alpha)})(g_{(2,\alpha)}\circ S_{\beta}(h))
\end{equation}
for all $g\in H_\alpha, h\in H_\beta,~ \alpha,\beta\in\pi$.

\label{pro:pi-bialg}
Let $(H,\cdot,\circ)$ be a Hopf $\pi$-brace, $H$ denote the Hopf $\pi$-algebra $(H, \cdot, S)$ and $H_{\circ}$ denote the Hopf $\pi$-algebra $(H,\circ,T)$.
\begin{enumerate}[\quad\rm(1)]
\item For all $g\in H_\alpha, h\in H_\beta$, $H$ is a left $H_{\circ}$-$\pi$-module like $\pi$-algebra with
    \begin{equation*} \label{eq:hbm:up}
     g\rightharpoonup_\alpha h=S_\alpha(g_{(1,\alpha)})(g_{(2,\alpha)}\circ h).
    \end{equation*}
\item For all $g\in H_\alpha, h\in H_\beta$,
    \begin{eqnarray*}
     &g\circ h=g_{(1,\alpha)}(g_{(2,\alpha)}\rightharpoonup_\alpha h),& \label{eq:hbm1}\\
     &gh=g_{(1,\alpha)}\circ(T_\alpha(g_{(2,\alpha)})\rightharpoonup_{\bar{\alpha}} h).& \label{eq:hbe1}
    \end{eqnarray*}
\item If $H$ is cocommutative, then $H$ is a left $H_{\circ}$-$\pi$-module like $\pi$-bialgebra and
\begin{equation*}
  S_\beta(g\rightharpoonup_\alpha h)=g\rightharpoonup_{\alpha} S_\beta(h), ~g\in H_\alpha, h\in H_\beta.
\end{equation*}
\end{enumerate}

Let $\pi_1$ and $\pi_2$ be two groups. A matched pair of Hopf $\pi$-algebras is a 4-tuple $(H, K,\leftharpoonup,\rightharpoonup)$, where $K$ is Hopf $\pi_1$-algebra and $H$ is Hopf $\pi_2$-algebra, $\rightharpoonup_{\alpha}:H_\alpha\otimes K_\gamma\rightarrow K_\gamma$ and $\leftharpoonup_{\gamma}:H_\alpha\otimes K_\gamma \rightarrow H_\alpha$ are linear maps such that $K_\beta$ is a left $\pi_2$-$H$-modulelike coalgebra and $H_\alpha$ is a right $\pi_1$-$K$-modulelike coalgebra and the following compatibility
conditions hold:
\begin{align}
x\rightharpoonup_{\gamma\delta}(ab)&=(x_{(1,\alpha)}\rightharpoonup_{\alpha}a_{(1,\gamma)})((x_{(2,\alpha)}\leftharpoonup_{\gamma}a_{(2,\gamma)})\rightharpoonup_\alpha b)),\label{mp1}\\
x\rightharpoonup_{\alpha}1_K&=\varepsilon_\alpha(x)1_K,\label{mp2}\\
(xy)\leftharpoonup_{\gamma}a&=(x\leftharpoonup_{\gamma}(y_{(1,\beta)}\rightharpoonup_{\beta}a_{(1,\gamma)}))(y_{(2,\beta)}\leftharpoonup_{\gamma}a_{(2,\gamma)}),\label{mp3}\\
1_H\leftharpoonup_e a&=\varepsilon_\gamma(a)1_H,\label{mp4}\\
(x_{(1,\alpha)}\leftharpoonup_\gamma a_{(1,\gamma)})\otimes(x_{(2,\alpha)}\rightharpoonup_\alpha a_{(2,\gamma)})&=(x_{(2,\alpha)}\leftharpoonup_\gamma a_{(2,\gamma)})\otimes(x_{(1,\alpha)}\rightharpoonup_\alpha a_{(1,\gamma)}),\label{mp5}
\end{align}
for all $x\in H_\alpha,y\in H_\beta,a\in K_\gamma,b\in K_\delta,\gamma,\delta\in\pi_1,\alpha,\beta\in\pi_2$.

\label{pro:mp}
Let $\pi$ be an abelian group and  $(H,\circ,\Delta,T)$ be a cocommutative Hopf $\pi$-algebra. Assume that $(H,H,\rightharpoonup,\leftharpoonup)$ is a matched pair and that 
\begin{equation}\label{mp6}
a\circ b=(a_{(1,\alpha)}\rightharpoonup_\alpha b_{(1,\beta)})\circ(a_{(2,\alpha)}\leftharpoonup_\beta b_{(2,\beta)}),
\end{equation}
for all $a\in H_\alpha,b\in H_\beta$. Then $(H,\cdot,\circ)$ is a Hopf $\pi$-brace with
$$ab=a_{(1,\alpha)}\circ(T_\alpha(a_{(2,\alpha)})\rightharpoonup_{\bar{\alpha}}b),\ S_\alpha(a)=a_{(1,\alpha)}\rightharpoonup_\alpha T_\alpha(a_{(2,\alpha)}).$$

\label{defi:pH}
A {\bf post-Hopf $\pi$-algebra} is a pair $(H,\triangleright)$, where $H=(\{H_\alpha\}_{\alpha\in\pi},\cdot,1,\Delta,\varepsilon,S)$ is a Hopf $\pi$-algebra and $\triangleright=\{\triangleright_{\alpha,\beta}:H_\alpha\otimes H_\beta\rightarrow H_\beta\}$ is a family of coalgebra homomorphisms satisfying 
\begin{eqnarray}
\label{eq:P1} &x\triangleright_{\alpha,\beta\gamma}(yz)=(x_{(1,\alpha)}\triangleright_{\alpha,\beta}y)(x_{(2,\alpha)}\triangleright_{\alpha,\gamma}z),&\\
\label{eq:P2} &x\triangleright_{\alpha,\gamma}(y\triangleright_{\beta,\gamma}z)=(x_{(1,\alpha)}(x_{(2,\alpha)}\triangleright_{\alpha,\beta}y))\triangleright_{\alpha\beta,\gamma}z,&
\end{eqnarray}
for any $x\in H_\alpha,y\in H_\beta,z\in H_\gamma$, and the linear map $\theta_{\alpha,\beta}:H_\alpha\rightarrow {\rm End}(H_\beta)$ defined by
$$\theta_{\alpha,\beta,x}(y)=x\triangleright_{\alpha,\beta}y$$
is convolution invertible in ${\rm Hom}(H_\alpha,{\rm End}(H_\beta))$, that is, there exists unique $\psi_{\alpha,\beta}\in{\rm Hom}(H_\alpha,{\rm End}(H_\beta))$ such that 
\begin{equation}\label{eq:P-con}
  \psi_{\alpha,\beta,x_{(1,\alpha)}}\theta_{\alpha,\beta,x_{(2,\alpha)}}=\theta_{\alpha,\beta,x_{(1,\alpha)}}\psi_{\alpha,\beta,x_{(2,{\alpha,\beta})}}=\varepsilon_\alpha(x)id_{H_\beta}.
\end{equation}

Let $(H,\triangleright)$ be a post-Hopf $\pi$-algebra. Then for all $x\in H_\alpha,y\in H_\beta, \alpha,\beta\in\pi$, we have
\begin{eqnarray}
\label{eq:P3} x\triangleright_{\alpha,e} 1 &=& \varepsilon_\alpha(x)1, \\
\label{eq:P4} 1\triangleright_{e,\alpha} x &=& x, \\
\label{eq:P5} S_\beta(x\triangleright_{\alpha,\beta} y) &=& x\triangleright_{\alpha,\bar{\beta}} S_\beta(y).
\end{eqnarray}

\label{thm:subHopf}
Let $(H,\triangleright)$ be a cocommutative post-Hopf $\pi$-algebra. Define
\begin{eqnarray}
\label{post-rbb-1} x *_{\alpha,\beta} y &:=& x_{(1,\alpha)}\cdot (x_{(2,\beta)}\triangleright_{\alpha,\beta} y),\\
\label{post-rbb-2} T_\alpha(x) &:=& \psi_{\alpha,\bar{\alpha},x_{(1,\alpha)}}(S_\alpha(x_{(2,\alpha)})),
\end{eqnarray}
for all $x\in H_\alpha,y\in H_\beta, \alpha,\beta\in\pi$. Then $H_\triangleright:=(H,*,1,\Delta,\varepsilon,T)$ is a Hopf $\pi$-algebra, which is called the {\bf subadjacent Hopf $\pi$-algebra}. Furthermore $(H_e,\cdot,1,\Delta_e,\varepsilon_e,S_e)$ is a left $H_\triangleright$-modulelike $\pi$-bialgebra under the action $\{\triangleright_{\alpha,e}\}_{\alpha\in\pi}$.

Let $H=\{H_\alpha\}_{\alpha\in\pi}$ be a cocommutative Hopf $\pi$-algebra. The family of coalgebra homomorphisms $B=\{B_\alpha:H_\alpha\rightarrow H_{\bar{\alpha}}\}_{\alpha\in\pi}$ is called a Rota-Baxter operator on $H$ if for all $\alpha,\beta\in\pi, a\in H_\alpha,b\in H_\beta$,
\begin{equation} \label{eq:RBO}
  B_\alpha(a)B_\beta(b)=B_{\beta\alpha}\big(a_{(1,\alpha)}B_\alpha(a_{(2,\alpha)})bS_{\bar{\alpha}}(B_\alpha(a_{(3,\alpha)}))\big).
\end{equation}
The pair $(H,B)$ is called a Rota-Baxter Hopf $\pi$-algebra.

\label{lem:nH}
Let $(H=\{H_\alpha\}_{\alpha\in\pi},B)$ be a Rota-Baxter Hopf $\pi$-algebra. Define
\begin{eqnarray}
& m_{\alpha,\beta}(g,h)=g\circ_B h:=g_{(1,\alpha)}B_\alpha(g_{(2,\alpha)})hS_{\bar{\alpha}}(B_\alpha(g_{(3,\alpha)})), & \label{eq:RBHm}\\
& T_\alpha(g):=S_{\bar{\alpha}}(B_\alpha(g_{(1,\alpha)}))S_\alpha(g_{(2,\alpha)})B_\alpha(g_{(3,\alpha)}), & \label{eq:RBHS}
\end{eqnarray}
for all $g\in H_\alpha,h\in H_\beta, ~\alpha,\beta\in\pi$.
\begin{enumerate}[\quad\rm(1)]
\item $H_B:=(H,m=\{m_{\alpha,\beta}\}_{\alpha\in\pi},T=\{T_{\alpha,\beta}\}_{\alpha\in\pi})$ is a cocommutative Hopf $\pi$-algebra.                                                          
\item For all $h\in H_\alpha$, $\alpha\in\pi$, we have
\begin{eqnarray}
 & B_\alpha(h_{(1,\alpha)})B_{\bar{\alpha}}(T_\alpha(h_{(2,\alpha)}))=\varepsilon_\alpha(h)1_e, \label{eq:t} & \\
 & B_{\bar{\alpha}}T_\alpha = S_{\bar{\alpha}}B_\alpha. &
\end{eqnarray}

\item The operator $B$ is also a Rota-Baxter operator on $H_B$, that is, $(H_B,B)$ is a Rota-Baxter Hopf $\pi$-algebra.
\item The family of maps $B:H_B\rightarrow H$ is a homomorphism of Rota-Baxter Hopf $\pi$-algebras.
\end{enumerate}

\label{thm:hb}
Let $(H=\{H_\alpha\}_{\alpha\in\pi},\cdot,B)$ be a Rota-Baxter Hopf $\pi$-algebra, and  the multiplication $\circ_B$ and antipode $T$ defined as (\ref{eq:RBHm}) and (\ref{eq:RBHS}). 
Then $(H,\cdot,\circ_B)$ is a cocommutative Hopf $\pi$-brace.
